import axios from 'axios';

// Python FastAPI Backend API URL
const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

const apiClient = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    'Content-Type': 'application/json',
  },
});

// Add auth header if token exists in localStorage
apiClient.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    return config;
  },
  (error) => Promise.reject(error)
);

// Response interceptor
apiClient.interceptors.response.use(
  (response) => response,
  (error) => Promise.reject(error)
);

export const apiService = {
  // Python User & Admin Sign In
  login: async (username, password) => {
    const response = await apiClient.post('/login', { username, password });
    return response.data;
  },

  // Python User Sign Up
  signup: async (data) => {
    const response = await apiClient.post('/signup', data);
    return response.data;
  },

  // Submit Contact Inquiry
  submitContactForm: async (data) => {
    const response = await apiClient.post('/contact', data);
    return response.data;
  },

  // Fetch Admin Registered Users
  getUsers: async () => {
    const response = await apiClient.get('/users');
    return response.data;
  },

  // Delete User Profile
  deleteUser: async (userId) => {
    const response = await apiClient.delete(`/users/${userId}`);
    return response.data;
  },

  // Fetch Message inquiries
  getMessages: async () => {
    const response = await apiClient.get('/messages');
    return response.data;
  },

  // Delete Inquiry Message
  deleteMessage: async (msgId) => {
    const response = await apiClient.delete(`/messages/${msgId}`);
    return response.data;
  },

  // Fetch Overview Stats
  getStats: async () => {
    const response = await apiClient.get('/stats');
    return response.data;
  },

  // Fetch System Audit Logs
  getLogs: async () => {
    const response = await apiClient.get('/logs');
    return response.data;
  },

  // Clear Audit Logs
  clearLogs: async () => {
    const response = await apiClient.post('/logs/clear');
    return response.data;
  }
};

export default apiService;
